from dataclasses import dataclass, field
from typing import List, Literal, Optional

@dataclass
class AudioChunk:
    chunk_id: str
    audio_content: bytes
    sample_rate_hertz: int

@dataclass
class SpeechRecognitionConfig:
    encoding: Literal['LINEAR16', 'FLAC', 'MULAW']
    sample_rate_hertz: int
    language_code: str
    enable_automatic_punctuation: bool = False

@dataclass
class StreamingRecognitionResult:
    transcript: str
    is_final: bool
    language_code: Optional[str] = None
    confidence: Optional[float] = None

@dataclass
class TranslationConfig:
    source_language_code: str
    target_language_code: str

@dataclass
class SafetyCheckResult:
    safe: bool
    scores: dict = field(default_factory=dict)

@dataclass
class SummaryResult:
    summary: str

@dataclass
class EmbeddingResult:
    embedding: List[float]

import os
from google.cloud import speech
from google.api_core.exceptions import GoogleAPICallError

class SpeechClient:
    """Provides a client for Google Cloud Speech-to-Text."""

    def __init__(self):
        # Initialize the Google Cloud Speech client. This assumes GOOGLE_APPLICATION_CREDENTIALS
        # environment variable is set or ADC is configured.
        self._client = speech.SpeechClient()

    def get_client(self):
        return self._client

    def create_streaming_config(self, config_params):
        """Creates a StreamingRecognitionConfig object."""
        recognition_config = speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding[config_params["encoding"]],
            sample_rate_hertz=config_params["sample_rate_hertz"],
            language_code=config_params["language_code"],
            enable_automatic_punctuation=config_params.get("enable_automatic_punctuation", False)
        )
        streaming_config = speech.StreamingRecognitionConfig(
            config=recognition_config,
            interim_results=True # Always enable interim results for streaming
        )
        return streaming_config

    def stream_recognize(self, streaming_config, audio_chunks_generator):
        """Yields streaming recognition responses."""
        requests = (speech.StreamingRecognizeRequest(audio_content=chunk) for chunk in audio_chunks_generator)
        try:
            for response in self._client.streaming_recognize(config=streaming_config, requests=requests):
                yield response
        except GoogleAPICallError as e:
            print(f"Google Cloud Speech API Error: {e}")
            raise

from speech_models import StreamingRecognitionResult

def handle_partial_results(recognition_result: StreamingRecognitionResult):
    """Handles partial streaming recognition results."""
    if not recognition_result.is_final:
        print(f"Partial Transcript: {recognition_result.transcript}")

def handle_final_results(recognition_result: StreamingRecognitionResult):
    """Handles final streaming recognition results."""
    if recognition_result.is_final:
        print(f"Final Transcript: {recognition_result.transcript}")
        # Here you might trigger other downstream processes like translation, safety check, summary
        return recognition_result.transcript
    return None

def process_streaming_transcription(results_generator):
    """Processes a generator of StreamingRecognitionResult objects."""
    for result in results_generator:
        handle_partial_results(result)
        final_transcript = handle_final_results(result)
        if final_transcript:
            yield final_transcript
